const summaryFields=[
  ['RegularHours','Regular hours'],
  ['OTHours','Regular OT'],
  ['OTExtHours','OT ext'],
  ['NightDiffHours','Night diff'],
  ['WDODays','WDO'],
  ['RestDayHours','WDO hours'],
