const pinnedSummaryKeys=new Set(['RegularHours','OTHours','OTExtHours','NightDiffHours','RestDayHours','RestDayOTHours','LateHours','UndertimeHours'])
const rows=ref<Row[]>([]),attendanceRows=ref<any[]>([]),holidays=ref<any[]>([]),shifts=ref<Shift[]>([]),search=ref(''),applied=ref(''),picker=ref(false),employeeSearch=ref(''),employees=ref<any[]>([]),selectedType=ref<'Regular'|'Reliever'>('Regular'),saving=ref(false),typeSaving=ref<number|null>(null),error=ref('')
const dayOpen=ref(false),dayForm=ref<any>(null),selectedRow=ref<Row|null>(null),batchOpen=ref(false),batchEmployee=ref<Row|null>(null),batchShift=ref(''),batchShiftSearch=ref(''),batchSuggestionsOpen=ref(false),batchResetting=ref(false),removeOpen=ref(false),removingEmployee=ref<number|null>(null)
