function dateOnly(value:unknown){const match=String(value||'').match(/\d{4}-\d{2}-\d{2}/);return match?.[0]||''}
function dayOfMonth(value:string){return Number(dateOnly(value).slice(-2))}
function sameEmployee(left:unknown,right:unknown){return String(left)===String(right)}
function dayLabel(value:string){return new Date(dateOnly(value)+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'})}
function dates(){const result:string[]=[];for(let d=new Date(dateOnly(props.dtr.PeriodStart)+'T00:00:00');d<=new Date(dateOnly(props.dtr.PeriodEnd)+'T00:00:00');d.setDate(d.getDate()+1))result.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'));return result}
function entry(row:Row,date:string){return attendanceMap.value.get(String(row.EmployeeID)+':'+date)}
function holidayAt(date:string){return holidayMap.value.get(date)}
function holidayTag(holiday:any){return holiday?.HolidayType==='Legal'?'LH':holiday?.HolidayType==='Special'?'SH':''}
function formatNumber(value:any){return Number(value||0).toFixed(2)}
function summaryStickyStyle(key:string){if(!pinnedSummaryKeys.has(key))return {};let right=150;for(const [field,width] of Object.entries(pinnedSummaryWidths)){if(field===key)break;right+=width}return {right:right+'px',minWidth:pinnedSummaryWidths[key]+'px',width:pinnedSummaryWidths[key]+'px'}}
function isWorkedDay(record:any){if(!record||noWorkAttendanceStatuses.has(normalizeAttendanceStatus(record.AttendanceStatus)))return false;const hasPaidTime=hourFields.filter(([key])=>!['LateHours','UndertimeHours','BreakHours'].includes(key)).some(([key])=>Number(record[key]||0)>0);return hasPaidTime||Boolean(record.TimeIn||record.TimeOut)}
function totalDays(row:Row){return attendanceRows.value.filter(item=>sameEmployee(item.EmployeeID,row.EmployeeID)&&isWorkedDay(item)).reduce((total,item)=>total+Math.max(1,Number(item.WorkdayCount||1)),0)}
