function formatSummary(value:any,key:string){return key==='WDODays'?String(Math.round(Number(value||0))):formatNumber(value)}
function shiftTag(row:Row){const labels:{[key:string]:string}={Day:'DS',Night:'NS',Split:'SS',DS:'DS',NS:'NS',MS:'MS',SS:'SS',Flexible:'FX'};const tags=[...new Set(attendanceRows.value.filter(item=>item.EmployeeID===row.EmployeeID).map(item=>Number(item.IsStraightDuty)===1?'SS':(item.ShiftType?(labels[item.ShiftType]||item.ShiftType):'')).filter(Boolean))];return tags.length?tags.join('/'):'-'}
function dayCellClass(row:Row,record:any){if(!record||normalizeAttendanceStatus(record.AttendanceStatus)==='Rest Day')return '';if(Number(record.IsStraightDuty)===1)return 'shift-ss';if(row.DefaultShiftCodeID&&String(record.ShiftCodeID)===String(row.DefaultShiftCodeID))return '';const shiftType=String(record.ShiftType||'').toUpperCase();return shiftType==='DS'?'shift-ds':shiftType==='NS'?'shift-ns':shiftType==='SS'?'shift-ss':''}
function cellText(record:any){if(!record)return '-';if(noWorkAttendanceStatuses.has(normalizeAttendanceStatus(record.AttendanceStatus)))return '';const regular=Number(record.RegularHours||0),rest=Number(record.RestDayHours||0),holiday=Number(record.LegalHolidayHours||0)+Number(record.SpecialHolidayHours||0);return regular||rest||holiday?formatNumber(regular||rest||holiday):''}
function cellSub(record:any){if(!record)return 'Click to add';if(noWorkAttendanceStatuses.has(normalizeAttendanceStatus(record.AttendanceStatus)))return '';const ot=Number(record.OTHours||0)+Number(record.OTExtHours||0);return ot?formatNumber(ot):record.ShiftCode||''}
function blankDay(row:Row,date:string){const item:any={EmployeeID:row.EmployeeID,AttendanceDate:date,ShiftCodeID:'',AttendanceStatus:'Present',AttendanceType:row.DeploymentType||'Regular',TimeIn:'',TimeOut:'',Remarks:'',LateHours:0,UndertimeHours:0,LateMinutes:0,UndertimeMinutes:0};hourFields.forEach(([key])=>item[key]=0);return item}
function nightDiffHours(timeIn:any,timeOut:any,shift:Shift){if(!shift.NDEnabled||!shift.NDStartTime||!shift.NDEndTime||!timeIn||!timeOut)return 0;const workStart=new Date(String(timeIn).replace(' ','T')),workEnd=new Date(String(timeOut).replace(' ','T'));if(Number.isNaN(workStart.getTime())||Number.isNaN(workEnd.getTime())||workEnd<=workStart)return 0;const startClock=String(shift.NDStartTime).slice(0,5),endClock=String(shift.NDEndTime).slice(0,5),cursor=new Date(workStart);cursor.setHours(0,0,0,0);cursor.setDate(cursor.getDate()-1);let milliseconds=0;while(cursor<=workEnd){const dateValue=cursor.getFullYear()+'-'+String(cursor.getMonth()+1).padStart(2,'0')+'-'+String(cursor.getDate()).padStart(2,'0'),windowStart=new Date(dateValue+'T'+startClock),windowEnd=new Date(dateValue+'T'+endClock);if(endClock<=startClock)windowEnd.setDate(windowEnd.getDate()+1);const from=Math.max(workStart.getTime(),windowStart.getTime()),to=Math.min(workEnd.getTime(),windowEnd.getTime());if(to>from)milliseconds+=to-from;cursor.setDate(cursor.getDate()+1)}return Math.round(milliseconds/3600000*100)/100}
function toInputDateTime(value:any){return value?String(value).replace('T',' ').slice(0,16):''}
async function load(){try{const result=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/records');rows.value=(result.records||[]).map((item:any)=>({...item,EmployeeID:Number(item.EmployeeID)}));attendanceRows.value=(result.attendanceRows||[]).map((item:any)=>({...item,EmployeeID:Number(item.EmployeeID),AttendanceDate:dateOnly(item.AttendanceDate),AttendanceStatus:normalizeAttendanceStatus(item.AttendanceStatus),ShiftCodeID:item.ShiftCodeID?String(item.ShiftCodeID):''}));holidays.value=result.holidays||[];shifts.value=result.shifts||[];if(!shifts.value.length){const fallback=await $fetch<any>('/api/organization/shift-code');const agencyId=Number(result.batch?.AgencyID||props.dtr.AgencyID||0);shifts.value=(fallback.items||[]).filter((shift:any)=>shift.Status==='Active'&&Number(shift.AgencyID)===agencyId)}if(!shifts.value.length)error.value='No active shift code is available for this DTR agency. Add or activate one under Shift Codes.'}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load DTR attendance.'}}
async function findEmployees(){try{const result=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{query:employeeSearch.value?{search:employeeSearch.value}:undefined});employees.value=result.employees||[]}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load employees.'}}
async function addEmployee(employee:any){saving.value=true;try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{method:'POST',body:{EmployeeID:employee.EmployeeID,DeploymentType:selectedType.value}});picker.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to add employee.'}finally{saving.value=false}}
async function removeDtrEmployee(row:Row){if(removingEmployee.value!==null||!confirm('Remove '+row.EmployeeName+' from this DTR? Their attendance for this cutoff will be deleted.'))return;removingEmployee.value=row.EmployeeID;error.value='';try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{method:'DELETE',body:{EmployeeID:row.EmployeeID}});await load();if(!rows.value.length)removeOpen.value=false;emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to remove employee from this DTR.'}finally{removingEmployee.value=null}}
async function updateType(row:Row,event:Event){const deploymentType=(event.target as HTMLSelectElement).value==='Reliever'?'Reliever':'Regular';typeSaving.value=row.EmployeeID;error.value='';try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{method:'PUT',body:{EmployeeID:row.EmployeeID,DeploymentType:deploymentType}});await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to update attendance type.';await load()}finally{typeSaving.value=null}}
function openBatch(row:Row){batchEmployee.value=row;batchShift.value='';batchShiftSearch.value='';batchSuggestionsOpen.value=false;batchOpen.value=true}
