async function applyBatch(){const row=batchEmployee.value,shift=selectedBatchShift.value;if(!row||!shift||saving.value)return;saving.value=true;error.value='';try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body:{ApplyBatch:true,EmployeeID:row.EmployeeID,ShiftCodeID:shift.ShiftCodeID,OnlyEmpty:false},timeout:20000});await load();batchOpen.value=false;emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to replace the cutoff attendance. Please try again.'}finally{saving.value=false}}
async function resetBatch(){const row=batchEmployee.value;if(!row||saving.value||batchResetting.value||!confirm('Reset '+row.EmployeeName+' to manual attendance? This clears every attendance entry in this cutoff.'))return;saving.value=true;batchResetting.value=true;error.value='';try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body:{ResetBatch:true,EmployeeID:row.EmployeeID},timeout:20000});await load();batchOpen.value=false;emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to reset the cutoff attendance. Please try again.'}finally{batchResetting.value=false;saving.value=false}}
function openDay(row:Row,date:string){selectedRow.value=row;const current=entry(row,date)||{};dayForm.value={...blankDay(row,date),...current,AttendanceDate:date,AttendanceStatus:normalizeAttendanceStatus(current.AttendanceStatus),ShiftCodeID:current.ShiftCodeID?String(current.ShiftCodeID):'',TimeIn:toInputDateTime(current.TimeIn),TimeOut:toInputDateTime(current.TimeOut),LateMinutes:Math.round(Number(current.LateHours||0)*60),UndertimeMinutes:Math.round(Number(current.UndertimeHours||0)*60)};dayOpen.value=true}
function refreshNightDiff(){const form=dayForm.value,shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form?.ShiftCodeID));if(form)form.NightDiffHours=shift?nightDiffHours(form.TimeIn,form.TimeOut,shift):0}
function adjustTimeOutFromHours(){const form=dayForm.value,shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form?.ShiftCodeID));if(!form||!shift||!form.TimeIn)return;const start=new Date(String(form.TimeIn).replace(' ','T')),regular=Number(form.RegularHours||0),ot=Number(form.OTHours||0),extension=Number(form.OTExtHours||0),total=regular+ot+extension;if(Number.isNaN(start.getTime())||!Number.isFinite(total)||total<0)return;const end=new Date(start.getTime()+Math.round(total*60)*60000);form.TimeOut=end.getFullYear()+'-'+String(end.getMonth()+1).padStart(2,'0')+'-'+String(end.getDate()).padStart(2,'0')+' '+String(end.getHours()).padStart(2,'0')+':'+String(end.getMinutes()).padStart(2,'0');refreshNightDiff()}
function applyShift(){const form=dayForm.value;if(!form)return;const shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form.ShiftCodeID));if(!shift)return;if(shift.ShiftType==='Flexible'&&(!shift.TimeIn||!shift.TimeOut)){form.RegularHours=0;form.OTHours=0;form.OTExtHours=0;form.TimeIn='';form.TimeOut='';form.NightDiffHours=0;return}form.RegularHours=Number(shift.RegularHours||0);form.OTHours=Number(shift.RegularOTCap||0);const inTime=String(shift.TimeIn).slice(0,5),outTime=String(shift.TimeOut).slice(0,5);form.TimeIn=form.AttendanceDate+'T'+inTime;const outDate=new Date(form.AttendanceDate+'T'+outTime);if(outTime<=inTime)outDate.setDate(outDate.getDate()+1);form.TimeOut=outDate.getFullYear()+'-'+String(outDate.getMonth()+1).padStart(2,'0')+'-'+String(outDate.getDate()).padStart(2,'0')+'T'+outTime;refreshNightDiff()}
function clearNonWorkAttendance(){const form=dayForm.value;if(!form)return;form.AttendanceStatus=normalizeAttendanceStatus(form.AttendanceStatus);if(!noWorkAttendanceStatuses.has(form.AttendanceStatus))return;form.ShiftCodeID='';form.TimeIn='';form.TimeOut='';hourFields.forEach(([key])=>form[key]=0);form.LateHours=0;form.UndertimeHours=0;form.LateMinutes=0;form.UndertimeMinutes=0}
function onAttendanceStatusChange(event:Event){if(!dayForm.value)return;dayForm.value.AttendanceStatus=normalizeAttendanceStatus((event.target as HTMLSelectElement).value);clearNonWorkAttendance()}
watch(()=>[dayForm.value?.RegularHours,dayForm.value?.OTHours,dayForm.value?.OTExtHours],()=>adjustTimeOutFromHours())
async function saveDay(){if(!dayForm.value)return;dayForm.value.AttendanceStatus=normalizeAttendanceStatus(dayForm.value.AttendanceStatus);clearNonWorkAttendance();saving.value=true;error.value='';try{const body={...dayForm.value,LateHours:Number(dayForm.value.LateMinutes||0)/60,UndertimeHours:Number(dayForm.value.UndertimeMinutes||0)/60};delete body.LateMinutes;delete body.UndertimeMinutes;await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body});dayOpen.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to save attendance.'}finally{saving.value=false}}
function importHeader(value:unknown){return String(value??'').trim().toLowerCase().replace(/[^a-z0-9]/g,'')}
function importValue(row:Record<string,unknown>,names:string[]){const wanted=new Set(names.map(importHeader));return Object.entries(row).find(([key])=>wanted.has(importHeader(key)))?.[1]??''}
function importDate(value:unknown){const raw=String(value??'').trim();if(!raw)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return raw;const parsed=new Date(raw);if(Number.isNaN(parsed.getTime()))return raw;return parsed.getFullYear()+'-'+String(parsed.getMonth()+1).padStart(2,'0')+'-'+String(parsed.getDate()).padStart(2,'0')}
function importTime(value:unknown){const raw=String(value??'').trim();if(!raw)return '';const match=raw.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i);if(!match)return raw;let hour=Number(match[1]);if(match[3]){if(hour===12)hour=0;if(match[3].toUpperCase()==='PM')hour+=12}return String(hour).padStart(2,'0')+':'+match[2]}
function openImport(){importOpen.value=true;importDragging.value=false;importFileName.value='';importRows.value=[];importResult.value=null;error.value=''}
async function readDtrImportFile(file?:File){importRows.value=[];importResult.value=null;if(!file)return;importFileName.value=file.name;error.value='';try{const XLSX=await import('xlsx');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const firstSheet=workbook.Sheets[workbook.SheetNames[0]];if(!firstSheet)throw new Error('The Excel file has no worksheet.');const sourceRows=XLSX.utils.sheet_to_json<Record<string,unknown>>(firstSheet,{defval:'',raw:false,dateNF:'yyyy-mm-dd'});if(!sourceRows.length)throw new Error('The first worksheet has no data rows.');const headers=Object.keys(sourceRows[0]||{}).map(importHeader);if(!headers.some(header=>['employeeid','employeeno','employeenumber'].includes(header))||!headers.includes('date'))throw new Error('Required columns: Employee ID or Employee No, and Date.');importRows.value=sourceRows.map((row,index)=>({RowNumber:index+2,EmployeeID:importValue(row,['Employee ID']),EmployeeNumber:importValue(row,['Employee No','Employee Number']),AttendanceDate:importDate(importValue(row,['Date','Attendance Date'])),ShiftCode:importValue(row,['Shift Code','Shift']),DateIn:importDate(importValue(row,['Date In'])),TimeIn:importTime(importValue(row,['Time In'])),DateOut:importDate(importValue(row,['Date Out'])),TimeOut:importTime(importValue(row,['Time Out'])),AttendanceStatus:importValue(row,['Status','Attendance Status'])}));}catch(e:any){importFileName.value='';error.value=e?.message||'Unable to read this Excel file.'}}
async function readDtrImport(event:Event){const input=event.target as HTMLInputElement;await readDtrImportFile(input.files?.[0]);input.value=''}
async function dropDtrImport(event:DragEvent){importDragging.value=false;await readDtrImportFile(event.dataTransfer?.files?.[0])}
async function submitDtrImport(){if(!importRows.value.length||importing.value)return;importing.value=true;error.value='';try{importResult.value=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body:{ImportRows:true,Rows:importRows.value},timeout:60000});await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to import the Excel attendance.'}finally{importing.value=false}}
function exportTime(value:unknown){const match=String(value||'').match(/[T\s](\d{2}:\d{2})/);return match?.[1]||''}
function exportDate(value:unknown){const raw=dateOnly(value);return raw?new Date(raw+'T00:00:00'):''}
