async function exportDtr(){if(exporting.value)return;exporting.value=true;error.value='';try{const result=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/records'),XLSX=await import('xlsx'),headers=['Employee ID','Employee Name','Date','Shift Code','Date In','Time In','Date Out','Time Out'],dutiesByDay=new Map<string,any[]>(),shiftCodeById=new Map((result.shifts||[]).map((item:any)=>[String(item.ShiftCodeID),item.ShiftCode]));for(const duty of result.dutyRows||[]){const key=String(duty.EmployeeID)+':'+dateOnly(duty.AttendanceDate),items=dutiesByDay.get(key)||[];items.push(duty);dutiesByDay.set(key,items)}const exportRows=(result.records||[]).flatMap((employee:any)=>dates().flatMap(date=>{const duties=dutiesByDay.get(String(employee.EmployeeID)+':'+date)||[];if(duties.length)return duties.map(item=>[item.EmployeeNumber||'EMP-'+String(item.EmployeeID).padStart(4,'0'),item.EmployeeName||employee.EmployeeName||'',exportDate(date),item.ShiftCode||'',exportDate(item.TimeIn),exportExcelTime(item.TimeIn),exportDate(item.TimeOut),exportExcelTime(item.TimeOut)]);return [[employee.EmployeeNumber||'EMP-'+String(employee.EmployeeID).padStart(4,'0'),employee.EmployeeName||'',exportDate(date),shiftCodeById.get(String(employee.DefaultShiftCodeID||''))||'','','','','']]}));const worksheet=XLSX.utils.aoa_to_sheet([headers,...exportRows]);for(let row=1;row<=exportRows.length;row++){for(const column of [2,4,6]){const cell=worksheet[XLSX.utils.encode_cell({r:row,c:column})];if(cell)cell.z='d-mmm-yy'}for(const column of [5,7]){const cell=worksheet[XLSX.utils.encode_cell({r:row,c:column})];if(cell)cell.z='h:mm'}}worksheet['!cols']=[{wch:16},{wch:30},{wch:14},{wch:20},{wch:14},{wch:12},{wch:14},{wch:12}];const workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,worksheet,'DTR');XLSX.writeFile(workbook,'DTR_'+dateOnly(props.dtr.PeriodStart)+'_to_'+dateOnly(props.dtr.PeriodEnd)+'.xlsx',{compression:true})}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Unable to export the DTR Excel file.'}finally{exporting.value=false}}
onMounted(load)
</script>

<template>
  <div class="dtr-attendance-layer">
    <section class="workspace">
      <button class="close" @click="emit('close')">x</button>
      <header><p>SUMMARY DAILY TIME RECORD</p><h2>{{ dtr.ClientName }} - {{ dtr.SiteName }}</h2><span>Payroll period: {{ dayLabel(dtr.PeriodStart) }} to {{ dayLabel(dtr.PeriodEnd) }}</span></header>
      <div class="toolbar"><input v-model.trim="search" placeholder="Search employee ID, number, or name"><button class="secondary" @click="applied=search">Search</button><button class="primary" @click="picker=true;findEmployees()">+ Add employee</button><button class="secondary" :disabled="!rows.length" @click="removeOpen=true">Remove people</button><button class="secondary" type="button" @click="openImport">Import</button><button class="secondary" type="button" :disabled="exporting" @click="exportDtr">{{exporting?'Exporting...':'Export'}}</button></div>
      <p class="hint">Click any day cell to add or update that employee's attendance for that date.</p><p v-if="error" class="error">{{error}}</p>
      <div class="table-wrap"><table class="cutoff-table"><thead><tr><th class="row-number" rowspan="2">No.</th><th class="person" rowspan="2">Name of personnel</th><th rowspan="2">Position</th><th rowspan="2">Type</th><th rowspan="2">Shift</th><th v-for="date in dates()" :key="date" :class="['day-head',{'holiday-day-head':holidayAt(date)}]" :title="holidayAt(date)?.HolidayName">{{dayOfMonth(date)}}<small v-if="holidayAt(date)">{{holidayTag(holidayAt(date))}}</small></th><th class="pinned-total-days" rowspan="2">Total days</th><th v-for="field in summaryFields" :key="field[0]" :class="{'pinned-summary':pinnedSummaryKeys.has(field[0])}" :style="summaryStickyStyle(field[0])" rowspan="2">{{field[1]}}</th><th class="signature pinned-signature" rowspan="2">Signature</th></tr><tr><th v-for="date in dates()" :key="date+'-hours'" class="day-hours">HRS</th></tr></thead>
        <tbody><tr v-for="(row,index) in visibleRows" :key="row.EmployeeID"><td>{{index+1}}</td><td class="person"><strong>{{row.EmployeeName}}</strong><small>EMP-{{String(row.EmployeeID).padStart(4,'0')}} / {{row.EmployeeNumber||'No employee no.'}}</small></td><td>{{row.PositionName||'-'}}</td><td><select class="type-select" :value="row.DeploymentType" :disabled="typeSaving===row.EmployeeID" @change="updateType(row,$event)"><option>Regular</option><option>Reliever</option></select></td><td class="shift-tag">{{shiftTag(row)}}<button class="batch-plus" title="Apply one shift to all cutoff days" @click="openBatch(row)">+</button></td><td v-for="date in dates()" :key="date" class="day-cell"><button :class="dayCellClass(row,entry(row,date))" :title="entry(row,date)?.HolidayName||holidayAt(date)?.HolidayName" @click="openDay(row,date)"><strong>{{cellText(entry(row,date))}}</strong><small>{{cellSub(entry(row,date))}}</small></button></td><td class="pinned-total-days">{{totalDays(row)}}</td><td v-for="field in summaryFields" :key="field[0]" :class="{'pinned-summary':pinnedSummaryKeys.has(field[0])}" :style="summaryStickyStyle(field[0])">{{formatSummary(summaryValue(row,field[0]),field[0])}}</td><td class="signature-cell pinned-signature"></td></tr><tr v-if="!rows.length"><td :colspan="7+dates().length+summaryFields.length" class="empty">No employee has been added to this DTR yet.</td></tr></tbody>
        <tfoot v-if="rows.length"><tr><th :colspan="5+dates().length">TOTAL</th><th class="pinned-total-days">{{visibleRows.reduce((sum,row)=>sum+totalDays(row),0)}}</th><th v-for="field in summaryFields" :key="field[0]" :class="{'pinned-summary':pinnedSummaryKeys.has(field[0])}" :style="summaryStickyStyle(field[0])">{{formatSummary(field[0]==='WDODays'?visibleRows.reduce((sum,row)=>sum+wdoDays(row),0):totals[field[0]],field[0])}}</th><th class="pinned-signature"></th></tr></tfoot>
      </table></div>
    </section>
    <div v-if="importOpen" class="layer" @click.self="importOpen=false"><section class="modal import-modal"><button class="close" type="button" @click="importOpen=false">x</button><h3>Import DTR from Excel</h3><p>Upload <strong>.xlsx, .xls, .xlsm, .xlsb, or .csv</strong>. Required: Employee ID or Employee No and Date. A row is worked only when it has both Time In and Time Out; a blank biometric row stays blank even if it has a Shift Code. Employee ID is matched first; Employee No is the fallback.</p><div class="file-drop" :class="{dragging:importDragging}" @dragenter.prevent="importDragging=true" @dragover.prevent="importDragging=true" @dragleave.prevent="importDragging=false" @drop.prevent="dropDtrImport"><label for="dtr-import-file"><strong>Drag and drop your Excel file here</strong><span>or click to choose a file</span></label><input id="dtr-import-file" type="file" accept=".xlsx,.xls,.xlsm,.xlsb,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,text/csv" @change="readDtrImport"></div><p v-if="importFileName" class="import-file"><strong>{{importFileName}}</strong> — {{importRows.length}} row{{importRows.length===1?'':'s'}} ready for validation.</p><div v-if="importRows.length" class="import-preview"><strong>Preview (first 6 rows)</strong><table><thead><tr><th>Row</th><th>Employee ID / No.</th><th>Date</th><th>Shift</th><th>Time in to out</th></tr></thead><tbody><tr v-for="row in importRows.slice(0,6)" :key="row.RowNumber"><td>{{row.RowNumber}}</td><td>{{row.EmployeeID||row.EmployeeNumber||'-'}}</td><td>{{row.AttendanceDate||'-'}}</td><td>{{row.ShiftCode||'-'}}</td><td>{{row.TimeIn||'-'}} to {{row.TimeOut||'-'}}</td></tr></tbody></table></div><div v-if="importResult" class="import-result"><strong>Import complete:</strong> {{importResult.imported}} added, {{importResult.updated}} updated, {{importResult.skipped}} skipped.<span v-if="importResult.blank"> {{importResult.blank}} blank biometric row{{importResult.blank===1?'':'s'}} left empty<span v-if="importResult.cleared">; {{importResult.cleared}} previous attendance row{{importResult.cleared===1?'':'s'}} cleared</span>.</span><ul v-if="importResult.issues?.length"><li v-for="issue in importResult.issues" :key="issue.row">Row {{issue.row}}: {{issue.reason}}</li></ul></div><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="importOpen=false">Close</button><button class="primary" type="button" :disabled="!importRows.length||importing" @click="submitDtrImport">{{importing?'Importing...':'Validate and import'}}</button></footer></section></div>
    <div v-if="removeOpen" class="layer" @click.self="removeOpen=false"><section class="modal remove-people-modal"><button class="close" @click="removeOpen=false">x</button><h3>Remove people from this DTR</h3><p>Removing a person deletes only their attendance in this cutoff. Their employee profile, rate, and other DTR records stay unchanged.</p><div class="remove-list"><div v-for="row in rows" :key="row.EmployeeID" class="remove-person"><div><strong>EMP-{{String(row.EmployeeID).padStart(4,'0')}} - {{row.EmployeeName}}</strong><span>{{row.EmployeeNumber||'No employee no.'}} / {{row.PositionName||'-'}} / {{row.DeploymentType}}</span></div><button class="secondary" :disabled="removingEmployee===row.EmployeeID" @click="removeDtrEmployee(row)">{{removingEmployee===row.EmployeeID?'Removing...':'× Remove'}}</button></div><p v-if="!rows.length">No employee is currently assigned to this DTR.</p></div><p v-if="error" class="error">{{error}}</p></section></div>
    <div v-if="picker" class="layer" @click.self="picker=false"><section class="modal employee-modal"><button class="close" @click="picker=false">x</button><h3>Add employee to this DTR</h3><p>Only employees under the DTR agency with an active rate for this client are shown.</p><div class="picker-tools"><input v-model.trim="employeeSearch" placeholder="Search employee ID, number, or name" @keyup.enter="findEmployees"><button class="secondary" @click="findEmployees">Search</button><select v-model="selectedType"><option>Regular</option><option>Reliever</option></select></div><div class="employee-list"><button v-for="employee in employees" :key="employee.EmployeeID" @click="addEmployee(employee)"><strong>EMP-{{String(employee.EmployeeID).padStart(4,'0')}} - {{employee.EmployeeName}}</strong><span>{{employee.EmployeeNumber||'No employee no.'}} / {{employee.PositionName}} / add as {{selectedType}}</span></button><p v-if="!employees.length">No eligible employee found for this client/site DTR.</p></div></section></div>
    <div v-if="batchOpen&&batchEmployee" class="layer" @click.self="batchOpen=false"><form class="modal batch-modal" @submit.prevent="applyBatch"><button class="close" type="button" @click="batchOpen=false">x</button><h3>Apply shift to cutoff</h3><p><strong>{{batchEmployee.EmployeeName}}</strong><br>Select one existing shift for this DTR agency to replace every day from {{dayLabel(dtr.PeriodStart)}} to {{dayLabel(dtr.PeriodEnd)}}.</p><label>Search shift code or name<div class="shift-combobox"><input v-model.trim="batchShiftSearch" type="search" autocomplete="off" placeholder="e.g. DS0700-1900 or Night shift" @focus="batchSuggestionsOpen=true" @input="batchShift='';batchSuggestionsOpen=true"><div v-if="batchSuggestionsOpen" class="shift-suggestions"><button v-for="shift in visibleBatchShifts" :key="shift.ShiftCodeID" type="button" @mousedown.prevent="selectBatchShift(shift)"><strong>{{shift.ShiftCode}}</strong><span>{{shift.ShiftName}} · {{shift.ShiftType}} · {{formatNumber(shift.RegularHours)}} / {{formatNumber(shift.RegularOTCap)}}</span></button><p v-if="!visibleBatchShifts.length">No matching active shift code for {{ dtr.AgencyName }}.</p></div></div></label><p v-if="selectedBatchShift" class="selected-shift">Selected: <strong>{{selectedBatchShift.ShiftCode}}</strong> — {{formatNumber(selectedBatchShift.RegularHours)}} regular / {{formatNumber(selectedBatchShift.RegularOTCap)}} OT for {{dates().length}} days.</p><p class="hint">Applying a shift replaces every day in this cutoff. For selected workdays only, reset this employee to blank manual entry first, then fill each day.</p><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="batchOpen=false">Cancel</button><button class="secondary" type="button" :disabled="saving||batchResetting" @click="resetBatch">{{batchResetting?'Resetting...':'Reset to manual entry'}}</button><button class="primary" type="submit" :disabled="saving||batchResetting||!batchShift">{{saving&&!batchResetting?'Applying...':'Apply shift to all days'}}</button></footer></form></div>
    <div v-if="dayOpen&&dayForm&&selectedRow" class="layer" @click.self="dayOpen=false"><form class="modal attendance-modal" @submit.prevent="saveDay"><button class="close" type="button" @click="dayOpen=false">x</button><h3>Attendance input</h3><p><strong>EMP-{{String(selectedRow.EmployeeID).padStart(4,'0')}} - {{selectedRow.EmployeeName}}</strong><br>{{dayLabel(dayForm.AttendanceDate)}} / {{dtr.ClientName}} - {{dtr.SiteName}}</p><div class="day-grid"><label>Shift code<select v-model="dayForm.ShiftCodeID" @change="applyShift"><option value="">No shift / manual</option><option v-for="shift in shifts" :key="shift.ShiftCodeID" :value="shift.ShiftCodeID">{{shift.ShiftCode}} - {{shift.ShiftName}} ({{shift.ShiftType}})</option></select></label><label>Status<select v-model="dayForm.AttendanceStatus" @change="onAttendanceStatusChange"><option>Present</option><option>Absent</option><option>Late</option><option>Half-Day</option><option>On-Leave</option><option>Holiday</option><option>Rest Day</option><option>Reliever</option></select></label><label>Time in<input v-model.trim="dayForm.TimeIn" type="text" inputmode="numeric" placeholder="YYYY-MM-DD HH:mm"></label><label>Time out<input v-model.trim="dayForm.TimeOut" type="text" inputmode="numeric" placeholder="YYYY-MM-DD HH:mm"></label><label v-for="field in hourFields" :key="field[0]">{{field[1]}}<input v-model.number="dayForm[field[0]]" type="number" min="0" max="24" step="0.01"></label><label>Late (minutes)<input v-model.number="dayForm.LateMinutes" type="number" min="0" max="1440" step="1" placeholder="e.g. 15"></label><label>Undertime (minutes)<input v-model.number="dayForm.UndertimeMinutes" type="number" min="0" max="1440" step="1" placeholder="e.g. 30"></label><label class="remarks">Remarks<textarea v-model.trim="dayForm.Remarks" maxlength="255"></textarea></label></div><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="dayOpen=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving...':'Save attendance'}}</button></footer></form></div>
  </div>
</template>

