<style>
/* Keep the common DTR view visible through WDO before horizontal scrolling. */
.dtr-attendance-layer .cutoff-table{min-width:0!important;font-size:9px}
.dtr-attendance-layer .cutoff-table th,.dtr-attendance-layer .cutoff-table td{padding:5px 3px}
.dtr-attendance-layer .cutoff-table .row-number{min-width:28px;width:28px}
.dtr-attendance-layer .cutoff-table .person{min-width:132px!important;width:132px;max-width:132px}
.dtr-attendance-layer .cutoff-table td:nth-child(3){min-width:56px;width:56px}
.dtr-attendance-layer .cutoff-table .type-select{width:64px!important;min-height:28px;padding:0 4px;font-size:9px}
.dtr-attendance-layer .cutoff-table .shift-tag{min-width:45px!important;width:45px;font-size:9px}
.dtr-attendance-layer .batch-plus{width:20px;height:20px;margin-left:3px;font-size:15px;line-height:18px}
.dtr-attendance-layer .cutoff-table .day-head,.dtr-attendance-layer .cutoff-table .day-cell{min-width:36px!important;width:36px}
.dtr-attendance-layer .day-cell button{min-height:48px;padding:4px 1px;font-size:9px}
.dtr-attendance-layer .day-cell small{font-size:8px}
/* Columns after the 16 date cells: Total Days, Regular, OT, OT Ext, Night Diff, WDO. */
.dtr-attendance-layer .cutoff-table th:nth-child(22),.dtr-attendance-layer .cutoff-table td:nth-child(22){min-width:48px;width:48px}
.dtr-attendance-layer .cutoff-table th:nth-child(23),.dtr-attendance-layer .cutoff-table td:nth-child(23){min-width:54px;width:54px}
.dtr-attendance-layer .cutoff-table th:nth-child(24),.dtr-attendance-layer .cutoff-table td:nth-child(24){min-width:50px;width:50px}
.dtr-attendance-layer .cutoff-table th:nth-child(25),.dtr-attendance-layer .cutoff-table td:nth-child(25),.dtr-attendance-layer .cutoff-table th:nth-child(26),.dtr-attendance-layer .cutoff-table td:nth-child(26){min-width:46px;width:46px}
.dtr-attendance-layer .cutoff-table th:nth-child(27),.dtr-attendance-layer .cutoff-table td:nth-child(27){min-width:38px;width:38px}
</style>
<style>
.dtr-attendance-layer .import-modal{width:min(860px,100%)}
.dtr-attendance-layer .file-picker{display:block;margin-top:18px;color:#415372;font-size:12px;font-weight:800}
.dtr-attendance-layer .file-picker input{display:block;width:100%;margin-top:7px;padding:9px}
.dtr-attendance-layer .file-drop{position:relative;margin-top:18px;border:2px dashed #aabddd;border-radius:10px;background:#f8fbff;transition:.16s ease}
.dtr-attendance-layer .file-drop:hover,.dtr-attendance-layer .file-drop.dragging{border-color:#2867d8;background:#eaf2ff}
.dtr-attendance-layer .file-drop label{display:flex;min-height:116px;box-sizing:border-box;align-items:center;justify-content:center;flex-direction:column;gap:6px;padding:18px;cursor:pointer;color:#1d4b9a;text-align:center}
.dtr-attendance-layer .file-drop label strong{font-size:15px}.dtr-attendance-layer .file-drop label span{color:#64738d;font-size:13px}
.dtr-attendance-layer .file-drop input{position:absolute;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none}
.dtr-attendance-layer .import-file{padding:10px 12px;border-radius:8px;background:#edf4ff;color:#294f8c!important}
.dtr-attendance-layer .import-preview{margin-top:14px;border:1px solid #dce5f1;border-radius:8px;overflow:auto}
.dtr-attendance-layer .import-preview>strong{display:block;padding:9px 11px;background:#f5f8fd;color:#415372;font-size:12px}
.dtr-attendance-layer .import-preview table{width:100%;border-collapse:collapse;font-size:12px}
.dtr-attendance-layer .import-preview th,.dtr-attendance-layer .import-preview td{padding:8px 10px;border-top:1px solid #e2e8f2;text-align:left;white-space:nowrap}
.dtr-attendance-layer .import-result{margin-top:14px;padding:12px;border-radius:8px;background:#edf8f0;color:#1d5b37;font-size:13px}
.dtr-attendance-layer .import-result ul{margin:8px 0 0;padding-left:20px;color:#7d2d20}
</style>
